import { useEffect, useRef, useState } from "react"
import {
  ArrowUpRight,
  CalendarDays,
  Clock3,
  Command,
  Database,
  GitBranch,
  Radio,
  Search,
  TrendingUp,
  UsersRound,
  Zap,
  type LucideIcon,
} from "lucide-react"

import { WorkspacesIcon } from "../../assets/icons"
import { DashboardLink } from "../navigation"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import {
  dashboardOverview,
  workspaceCards,
  type WorkspaceCard,
} from "../../data"

const workspaceIcons: Record<WorkspaceCard["icon"], LucideIcon> = {
  database: Database,
  flexibility: Zap,
  planning: TrendingUp,
  operations: Radio,
  stakeholders: UsersRound,
  connections: GitBranch,
}

function SectionTitle({
  children,
  icon: Icon,
}: {
  children: string
  icon?: LucideIcon
}) {
  return (
    <h2 className="flex items-center gap-2 text-sm font-medium">
      {Icon ? (
        <Icon aria-hidden="true" className="size-5" strokeWidth={1.6} />
      ) : (
        <WorkspacesIcon aria-hidden="true" className="size-5" />
      )}
      {children}
    </h2>
  )
}

function WorkspaceCardItem({ workspace }: { workspace: WorkspaceCard }) {
  const Icon = workspaceIcons[workspace.icon]

  return (
    <DashboardLink
      href={workspace.href}
      className="rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      <Card
        size="sm"
        className="h-full gap-11 bg-secondary shadow-none ring-0 transition-colors hover:bg-secondary/80 dark:bg-card/60 dark:hover:bg-card"
      >
        <CardHeader className="flex flex-row items-start justify-between">
          <span className="grid size-10 place-items-center rounded-lg bg-background">
            <Icon aria-hidden="true" className="size-5" strokeWidth={1.6} />
          </span>
          <ArrowUpRight
            aria-hidden="true"
            className="size-6 text-muted-foreground"
            strokeWidth={1.5}
          />
        </CardHeader>
        <CardContent className="space-y-3">
          <CardTitle>{workspace.title}</CardTitle>
          <CardDescription className="font-mono text-xs">
            <ul className="space-y-2">
              {workspace.details.map((detail) => (
                <li key={detail} className="flex gap-2">
                  <span aria-hidden="true">·</span>
                  <span>{detail}</span>
                </li>
              ))}
            </ul>
          </CardDescription>
        </CardContent>
      </Card>
    </DashboardLink>
  )
}

export function DashboardContent() {
  const [query, setQuery] = useState("")
  const searchInputRef = useRef<HTMLInputElement>(null)
  const normalizedQuery = query.trim().toLowerCase()
  const visibleWorkspaces = workspaceCards.filter((workspace) =>
    [workspace.title, ...workspace.details]
      .join(" ")
      .toLowerCase()
      .includes(normalizedQuery)
  )

  useEffect(() => {
    function focusSearch(event: KeyboardEvent) {
      if (
        (event.ctrlKey || event.metaKey) &&
        event.key.toLowerCase() === "k"
      ) {
        event.preventDefault()
        searchInputRef.current?.focus()
      }
    }

    window.addEventListener("keydown", focusSearch)
    return () => window.removeEventListener("keydown", focusSearch)
  }, [])

  return (
    <div className="mx-auto w-full max-w-screen-2xl px-4 py-6 sm:px-6 lg:px-8 lg:pt-12">
      <div className="flex flex-col gap-6 border-b pb-5 lg:flex-row lg:items-end lg:justify-between">
        <div className="space-y-4">
          <h1 className="text-2xl font-medium tracking-tight sm:text-3xl">
            {dashboardOverview.company}
          </h1>
          <p className="flex items-center gap-1.5 font-mono text-sm text-muted-foreground sm:text-base">
            <CalendarDays aria-hidden="true" className="size-5" strokeWidth={1.5} />
            {dashboardOverview.date}
          </p>
        </div>

        <div className="relative w-full lg:max-w-md">
          <label htmlFor="network-search" className="sr-only">
            Search the network model
          </label>
          <Search
            aria-hidden="true"
            className="pointer-events-none absolute left-4 top-1/2 size-5 -translate-y-1/2 text-muted-foreground"
            strokeWidth={1.5}
          />
          <Input
            id="network-search"
            ref={searchInputRef}
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search the network model..."
            className="h-11 rounded-lg border-0 bg-muted pl-11 pr-4 font-mono shadow-none sm:pr-14 [&::-webkit-search-cancel-button]:appearance-none"
          />
          <div className="absolute right-2 top-1/2 -translate-y-1/2">
            <kbd className="pointer-events-none hidden items-center gap-1 rounded-md bg-background px-2 py-1 font-mono text-xs text-muted-foreground sm:flex">
              <Command aria-hidden="true" className="size-3" />
              K
            </kbd>
          </div>
        </div>
      </div>

      <section className="mt-7">
        <SectionTitle icon={Clock3}>Recents</SectionTitle>
        <div className="flex flex-col items-center gap-5 py-10 sm:py-12">
          <span className="grid size-14 place-items-center rounded-xl bg-muted">
            <Clock3 aria-hidden="true" className="size-7" strokeWidth={1.5} />
          </span>
          <p className="font-mono text-sm text-muted-foreground">
            Your recent works will appear here
          </p>
        </div>
      </section>

      <section className="space-y-6 pb-8">
        <SectionTitle>Workspaces</SectionTitle>

        {visibleWorkspaces.length > 0 ? (
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3 xl:gap-6">
            {visibleWorkspaces.map((workspace) => (
              <WorkspaceCardItem key={workspace.title} workspace={workspace} />
            ))}
          </div>
        ) : (
          <p className="flex min-h-48 items-center justify-center rounded-xl bg-muted text-center text-sm text-muted-foreground">
            No workspaces match your search.
          </p>
        )}
      </section>
    </div>
  )
}

import { useEffect, useState } from "react"
import {
  ArrowLeft,
  ArrowUpRight,
  ChevronLeft,
  Database,
  GitBranch,
  Info,
  Shield,
  type LucideIcon,
} from "lucide-react"

import { DashboardLink } from "../navigation"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer"
import {
  modellingActions,
  modellingDashboard,
  modelWorkflowStatuses,
  networkBasemapUrl,
  networkRegions,
  type ModellingAction,
  type NetworkRegion,
} from "../../data"
import { cn } from "@/lib/utils"

const actionIcons: Record<ModellingAction["icon"], LucideIcon> = {
  database: Database,
  comparison: GitBranch,
  clearview: Shield,
}

const markerStyles: Record<NetworkRegion["color"], string> = {
  blue: "border-blue-700 bg-blue-500",
  purple: "border-violet-700 bg-violet-500",
  red: "border-red-700 bg-red-500",
  green: "border-emerald-700 bg-emerald-500",
}

const markerPositions: Record<NetworkRegion["position"], string> = {
  "north-east": "right-3 top-[9%] lg:left-[72%] lg:right-auto",
  central: "right-12 top-[28%] lg:left-[57%] lg:right-auto",
  west: "left-3 top-[50%] lg:left-[40%]",
  "south-east": "right-6 top-[71%] lg:left-[68%] lg:right-auto",
}

function StatusDotLabel({ children }: { children: string }) {
  return (
    <p className="flex items-center gap-2 text-xs text-muted-foreground">
      <span className="size-1.5 rounded-full bg-current" />
      {children}
    </p>
  )
}

function ModelSummary() {
  return (
    <div className="grid grid-cols-2 gap-3">
      <div className="space-y-7 rounded-xl bg-secondary/70 p-4">
        <StatusDotLabel>Current Model</StatusDotLabel>
        <div className="space-y-2">
          <p className="text-sm font-medium">{modellingDashboard.currentModel}</p>
          <p className="font-mono text-xs text-primary">
            {modellingDashboard.currentVersion}
          </p>
        </div>
      </div>

      <div className="space-y-7 rounded-xl bg-secondary/70 p-4">
        <StatusDotLabel>Latest Update</StatusDotLabel>
        <p className="text-sm font-medium leading-snug">
          {modellingDashboard.latestUpdate}
        </p>
      </div>

      <div className="col-span-2 space-y-7 rounded-xl bg-secondary/70 p-4">
        <StatusDotLabel>Status</StatusDotLabel>
        <div className="space-y-3">
          <p className="flex items-end gap-2">
            <span className="text-base font-medium">
              {modellingDashboard.coverage}
            </span>
            <span className="text-xs text-muted-foreground">Coverage</span>
          </p>
          <div className="flex flex-wrap items-center justify-between gap-2 text-xs">
            <p className="text-muted-foreground">
              Last Published:{" "}
              <span className="text-foreground/80">
                {modellingDashboard.lastPublished}
              </span>
            </p>
            <p className="text-amber-500">
              {modellingDashboard.openIssues} open issues
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

function PrimaryAction({ action }: { action: ModellingAction }) {
  const Icon = actionIcons[action.icon]

  return (
    <button
      type="button"
      className="group flex min-h-40 flex-col justify-between gap-8 rounded-xl bg-secondary/70 p-4 text-left outline-none transition-colors hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring"
    >
      <span className="flex w-full items-start justify-between">
        <span className="grid size-10 place-items-center rounded-lg bg-background">
          <Icon aria-hidden="true" className="size-5" strokeWidth={1.5} />
        </span>
        <ArrowUpRight
          aria-hidden="true"
          className="size-5 text-muted-foreground transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5"
          strokeWidth={1.5}
        />
      </span>
      <span className="space-y-2">
        <span className="block text-sm font-medium">{action.title}</span>
        <span className="block font-mono text-xs leading-relaxed text-muted-foreground">
          {action.description}
        </span>
      </span>
    </button>
  )
}

function RegionMarker({
  region,
  selected,
  onSelect,
}: {
  region: NetworkRegion
  selected: boolean
  onSelect: () => void
}) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      onClick={onSelect}
      className={cn(
        "absolute w-36 rounded-xl border-2 p-2 text-left text-primary-foreground shadow-lg outline-none transition-transform hover:-translate-y-0.5 focus-visible:ring-2 focus-visible:ring-foreground lg:w-48 lg:p-4",
        markerStyles[region.color],
        markerPositions[region.position],
        selected && "border-foreground"
      )}
    >
      <span className="block text-sm font-medium">{region.name}</span>
      <span className="mt-2 flex items-center gap-2 font-mono text-xs text-primary-foreground/80">
        Click to load
        <ArrowUpRight aria-hidden="true" className="size-4" />
      </span>
    </button>
  )
}

function MapLegend() {
  return (
    <div className="absolute bottom-5 right-5 hidden space-y-1.5 rounded-lg bg-black/30 p-3 backdrop-blur-sm lg:block">
      {networkRegions.map((region) => (
        <div
          key={`${region.legendName}-${region.color}`}
          className="flex items-center gap-2 font-mono text-xs text-primary-foreground/80"
        >
          <span
            className={cn(
              "size-2 rounded-sm",
              markerStyles[region.color].split(" ")[1]
            )}
          />
          {region.legendName}
        </div>
      ))}
    </div>
  )
}

function Map() {
  const [selectedRegion, setSelectedRegion] = useState<string>()

  return (
    <div className="absolute inset-0 overflow-hidden bg-black">
      <img
        src={networkBasemapUrl}
        alt="Network regions across Maryland and Delaware"
        className="size-full object-cover object-center invert dark:invert-0"
      />
      <div className="absolute inset-0 bg-black/10" />
      {networkRegions.map((region) => {
        const key = `${region.name}-${region.color}`
        return (
          <RegionMarker
            key={key}
            region={region}
            selected={selectedRegion === key}
            onSelect={() => setSelectedRegion(key)}
          />
        )
      })}
      <MapLegend />
    </div>
  )
}

function InformationPanelHeader() {
  return (
    <DashboardLink
      href="/"
      className="inline-flex items-center gap-2 rounded-md py-1 text-sm text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
    >
      <ArrowLeft aria-hidden="true" className="size-4" />
      Go back to home
    </DashboardLink>
  )
}

function InformationPanelBody() {
  return (
    <div className="space-y-8">
      <section className="space-y-6">
        <span className="grid size-10 place-items-center rounded-lg bg-secondary">
          <Database aria-hidden="true" className="size-5" strokeWidth={1.5} />
        </span>
        <div className="space-y-3">
          <h1 className="text-xl font-medium tracking-tight">
            {modellingDashboard.title}
          </h1>
          <p className="max-w-sm font-mono text-xs leading-relaxed text-muted-foreground">
            {modellingDashboard.description}
          </p>
          <div className="flex flex-wrap items-center gap-1 font-mono text-xs">
            <span className="rounded-md bg-secondary px-2 py-1 text-muted-foreground">
              {modellingDashboard.version}
            </span>
            <span className="flex items-center gap-2 rounded-md bg-secondary px-2 py-1 text-primary">
              <span className="size-1.5 rounded-full bg-primary" />
              {modelWorkflowStatuses.publication}
            </span>
            <span className="rounded-md bg-secondary px-2 py-1 text-emerald-500">
              {modelWorkflowStatuses.validation}
            </span>
          </div>
        </div>
      </section>

      <ModelSummary />

      <section className="space-y-4">
        <h2 className="flex items-center gap-2 font-mono text-base text-foreground/80">
          <ArrowUpRight aria-hidden="true" className="size-5" />
          Primary Actions
        </h2>
        <div className="grid gap-3 sm:grid-cols-2">
          {modellingActions.map((action) => (
            <PrimaryAction key={action.title} action={action} />
          ))}
        </div>
      </section>
    </div>
  )
}

function DesktopInformationPanel() {
  const [isOpen, setIsOpen] = useState(true)

  if (!isOpen) {
    return (
      <Button
        type="button"
        variant="secondary"
        size="sm"
        aria-label="Open model information"
        onClick={() => setIsOpen(true)}
        className="absolute left-4 top-4 z-20 hidden shadow-lg md:inline-flex"
      >
        <Info aria-hidden="true" />
        Model details
      </Button>
    )
  }

  return (
    <article className="absolute inset-y-4 left-4 z-10 hidden w-96 flex-col overflow-hidden rounded-xl bg-background/95 p-6 shadow-2xl backdrop-blur-xl md:flex">
      <Button
        type="button"
        variant="ghost"
        size="icon-lg"
        aria-label="Collapse model information"
        onClick={() => setIsOpen(false)}
        className="absolute right-3 top-3 text-muted-foreground"
      >
        <ChevronLeft aria-hidden="true" className="size-6" />
      </Button>
      <div className="shrink-0">
        <InformationPanelHeader />
      </div>
      <div className="mt-8 min-h-0 flex-1 overflow-y-auto">
        <InformationPanelBody />
      </div>
    </article>
  )
}

function MobileInformationDrawer() {
  const [isOpen, setIsOpen] = useState(false)

  useEffect(() => {
    const desktopQuery = window.matchMedia("(min-width: 48rem)")
    const closeOnDesktop = (event: MediaQueryListEvent) => {
      if (event.matches) setIsOpen(false)
    }

    desktopQuery.addEventListener("change", closeOnDesktop)
    return () => desktopQuery.removeEventListener("change", closeOnDesktop)
  }, [])

  return (
    <Drawer open={isOpen} onOpenChange={setIsOpen}>
      <DrawerTrigger
        className={cn(
          buttonVariants({ variant: "secondary", size: "sm" }),
          "absolute left-4 top-4 z-20 shadow-lg md:hidden",
        )}
      >
        <Info aria-hidden="true" />
        Model details
      </DrawerTrigger>
      <DrawerContent className="md:hidden">
        <DrawerHeader className="sr-only">
          <DrawerTitle>{modellingDashboard.title}</DrawerTitle>
          <DrawerDescription>
            Network model information and primary actions
          </DrawerDescription>
        </DrawerHeader>
        <article className="flex min-h-0 flex-1 flex-col px-5 pb-8 pt-3">
          <div className="shrink-0">
            <InformationPanelHeader />
          </div>
          <div className="mt-8 min-h-0 flex-1 overflow-y-auto">
            <InformationPanelBody />
          </div>
        </article>
      </DrawerContent>
    </Drawer>
  )
}

export function ModellingDashboard() {
  return (
    <div className="absolute inset-x-0 bottom-0 top-18 overflow-hidden bg-background md:left-17">
      <Map />
      <DesktopInformationPanel />
      <MobileInformationDrawer />
    </div>
  )
}

import { useEffect, useState, type ReactNode } from "react"

import { TooltipProvider } from "@/components/ui/tooltip"

import { AppSidebar } from "./app-sidebar"
import { TopNavbar } from "./top-navbar"

export function DashboardShell({ children }: { children: ReactNode }) {
  const [isDark, setIsDark] = useState(() =>
    typeof document === "undefined"
      ? false
      : document.documentElement.classList.contains("dark")
  )

  useEffect(() => {
    const root = document.documentElement
    const syncTheme = () => setIsDark(root.classList.contains("dark"))
    const observer = new MutationObserver(syncTheme)

    syncTheme()
    observer.observe(root, {
      attributes: true,
      attributeFilter: ["class"],
    })

    return () => observer.disconnect()
  }, [])

  function handleThemeChange(dark: boolean) {
    document.documentElement.classList.toggle("dark", dark)
    localStorage.setItem("theme", dark ? "dark" : "light")
    setIsDark(dark)
  }

  return (
    <TooltipProvider>
      <div
        className="relative h-svh min-h-0 overflow-hidden transition-colors"
      >
        <AppSidebar />
        <TopNavbar
          isDark={isDark}
          onThemeChange={handleThemeChange}
        />

        <main
          aria-label="Page content"
          className="h-full overflow-y-auto pt-18 md:pl-17"
        >
          {children}
        </main>
      </div>
    </TooltipProvider>
  )
}

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { LucideIcon } from "lucide-react";

import { useDashboardNavigation } from "../navigation";

export type NavigationItem = {
  href: string;
  label: string;
  shortLabel: string;
  icon: LucideIcon;
};

type SidebarNavigationItemProps = {
  item: NavigationItem;
  showLabel?: boolean;
  onNavigate?: () => void;
};

export function SidebarNavigationItem({
  item,
  showLabel = false,
  onNavigate,
}: SidebarNavigationItemProps) {
  const { pathname, navigate } = useDashboardNavigation();
  const active =
    item.href === "/"
      ? pathname === item.href
      : pathname.startsWith(item.href);
  const Icon = item.icon;
  const className = cn(
    buttonVariants({
      variant: "ghost",
      size: showLabel ? "lg" : "icon-lg",
    }),
    "rounded-lg text-muted-foreground",
    showLabel && "w-full justify-start gap-3",
    active &&
      "bg-primary/10 text-primary hover:bg-primary/20 hover:text-primary",
  );

  const content = (
    <>
      <Icon
        aria-hidden="true"
        className={showLabel ? "size-5" : "size-6"}
        strokeWidth={showLabel ? 1.7 : 1.6}
      />
      {showLabel && item.shortLabel}
    </>
  );
  const handleNavigate = () => {
    navigate(item.href);
    onNavigate?.();
  };

  if (showLabel) {
    return (
      <button
        type="button"
        aria-current={active ? "page" : undefined}
        className={className}
        onClick={handleNavigate}
      >
        {content}
      </button>
    );
  }

  return (
    <Tooltip>
      <TooltipTrigger
        type="button"
        aria-label={item.label}
        aria-current={active ? "page" : undefined}
        className={className}
        onClick={handleNavigate}
      >
        {content}
      </TooltipTrigger>
      <TooltipContent side="right">{item.label}</TooltipContent>
    </Tooltip>
  );
}

import { ArrowRight, MoonStar, SunDim } from "lucide-react"

import { Switch } from "@/components/ui/switch"

import { modellingDashboard, modelWorkflowStatuses } from "../../data"
import { useDashboardNavigation } from "../navigation"
import { ProfileMenu } from "../shared/profile-menu"
import { MobileNavigation, primaryNavigation } from "./app-sidebar"

type TopbarProps = {
  isDark: boolean
  onThemeChange: (isDark: boolean) => void
}

function StatusStrip() {
  return (
    <div className="hidden h-6.5 shrink-0 items-center overflow-hidden rounded-md bg-muted font-mono text-xs tracking-tight sm:flex">
      <span className="flex h-full items-center gap-2 border-r-2 border-sidebar px-2.5 text-primary">
        <span className="size-1.5 rounded-full bg-primary" />
        {modelWorkflowStatuses.publication}
      </span>
      <span className="flex h-full items-center border-r-2 border-sidebar px-2.5 text-emerald-500">
        {modelWorkflowStatuses.validation}
      </span>
      <span className="flex h-full items-center px-2.5 text-muted-foreground">
        {modelWorkflowStatuses.review}
      </span>
    </div>
  )
}

function DesktopThemeToggle({
  isDark,
  onThemeChange,
}: {
  isDark: boolean
  onThemeChange: (isDark: boolean) => void
}) {
  const ThemeIcon = isDark ? MoonStar : SunDim

  return (
    <div className="hidden items-center gap-3 md:flex">
      <div className="flex items-center gap-1">
        <ThemeIcon
          aria-hidden="true"
          className={isDark ? "size-4" : "size-4.5"}
          strokeWidth={1.5}
        />
        <span>{isDark ? "Dark Mode" : "Light Mode"}</span>
      </div>
      <Switch
        checked={isDark}
        onCheckedChange={onThemeChange}
        aria-label={`Switch to ${isDark ? "light" : "dark"} mode`}
        className="data-unchecked:bg-muted"
      />
    </div>
  )
}

export function TopNavbar({
  isDark,
  onThemeChange,
}: TopbarProps) {
  const { pathname } = useDashboardNavigation()
  const activeLabel =
    primaryNavigation.find((item) =>
      item.href === "/"
        ? pathname === item.href
        : pathname.startsWith(item.href),
    )?.shortLabel ?? "Dashboard"

  return (
    <header className="absolute left-0 right-0 top-0 z-20 flex h-18 items-center justify-between gap-3 border-b border-sidebar-border bg-sidebar px-3 text-sidebar-foreground sm:px-5 md:left-17 md:px-8">
      <div className="flex min-w-0 items-center gap-3">
        <MobileNavigation
          isDark={isDark}
          onThemeChange={onThemeChange}
        />
        <span className="truncate text-sm font-semibold sm:hidden">
          {activeLabel}
        </span>
        <StatusStrip />
      </div>

      <div className="flex min-w-0 items-center gap-4 font-mono text-xs text-muted-foreground lg:gap-6">
        <div className="hidden min-w-0 items-center gap-2 lg:flex">
          <span className="truncate">
            {modellingDashboard.currentModel} Model
          </span>
          <span className="size-1 rounded-full bg-muted-foreground" />
          <span>{modellingDashboard.currentVersion}</span>
